#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# WHAT: walks the maintainer through cutting release vX.Y.Z on every channel: the merge of the
#       spec's pull request, the checks on main, the release settings, the tag and its push, the
#       Release run (with the npm and MCP Registry fallbacks), the check of what was published and
#       the closing of the milestone. It publishes nothing by itself: the tag push, a secret, a
#       job re-run and the closing of the milestone each wait for a confirmation that names them.
# WHY:  a publication cannot be undone, the tag ruleset lets nobody but the maintainer push a
#       v* tag, and every step the agent could do before the tag is already committed
#       (docs/development/release-pipeline.md "Cutting a release").
# WHEN: when the work of the release is reviewed and its pull request is ready to merge. Stop
#       any time with Ctrl-C; nothing is half-done between two confirmations, and a re-run before
#       the tag is pushed starts again from the preflight. Once the tag exists the preflight stops
#       a re-run: continue by hand with docs/development/release-pipeline.md ("If the wizard stops
#       after the tag").
# HOW:  ./scripts/release-wizard.sh X.Y.Z   (from anywhere inside the repo, for example 0.2.0)
#       RELEASE_MILESTONE, RELEASE_SPEC and RELEASE_EXIT_ISSUES name the milestone, the spec and
#       the exit-check tickets of stages 2, 3 and 11; they default to the ones of v0.2.0.

REPO="rodrigorjsf/langfuse-api-mcp"
MILESTONE="${RELEASE_MILESTONE:-M8 Older-deployment fidelity}"
SPEC_ISSUE="${RELEASE_SPEC:-172}"
EXIT_ISSUES="${RELEASE_EXIT_ISSUES:-183 184 185}"

usage() {
  printf 'Usage: release-wizard.sh X.Y.Z\n' >&2
  printf '  X.Y.Z is the release version without the leading v, for example 0.2.0.\n' >&2
  printf '  It changes nothing before the stages start, and nothing without a confirmation.\n' >&2
}

# The version is checked before anything else runs: no command, no file, no screen change.
if [[ $# -ne 1 || ! "$1" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  usage
  exit 2
fi
VERSION="$1"
TAG="v$VERSION"

cd "$(git rev-parse --show-toplevel)"

# No value this wizard reads is saved: the library reads and writes ENV_FILE, so it points at a
# place that is no file. The wizard calls neither write_env nor set_secret.
ENV_FILE=/dev/null

TOTAL_STAGES=11

AFTER_TAG=0   # becomes 1 once the tag is pushed: from then on a re-run stops in the preflight
RUN_ID=""
RUN_URL=""
TRANSCRIPT="${TMPDIR:-/tmp}/lfmcp-$TAG-release-proofs.txt"
NPM_PACKAGES=(
  langfuse-api-mcp
  langfuse-api-mcp-linux-x64 langfuse-api-mcp-linux-arm64
  langfuse-api-mcp-darwin-x64 langfuse-api-mcp-darwin-arm64
  langfuse-api-mcp-win32-x64 langfuse-api-mcp-win32-arm64
)

have() { command -v "$1" >/dev/null 2>&1; }

die() { warn "$1"; exit 1; }

# stop_unless "question" — a confirmation that ends the wizard on "no" (or on no answer at all).
# Everything outward sits behind one, and the question names what is about to happen.
stop_unless() {
  if confirm "$1"; then return 0; fi
  printf '\n'
  if (( AFTER_TAG )); then
    warn "stopped. $TAG is tagged: a re-run stops in the preflight. Continue by hand with docs/development/release-pipeline.md (\"If the wizard stops after the tag\")."
  else
    warn "stopped, nothing further was changed. Re-run: scripts/release-wizard.sh $VERSION"
  fi
  exit 1
}

# job_conclusion NAME — the conclusion of a job of the latest attempt of the Release run (empty while it runs).
job_conclusion() {
  gh run view "$RUN_ID" -R "$REPO" --json jobs --jq ".jobs[] | select(.name == \"$1\") | .conclusion" 2>/dev/null | head -n 1 || true
}

# watch_run — print the state of the release jobs every 15 seconds until the run ends.
watch_run() {
  local status="" lines="" shown="" unknown=0
  while :; do
    status=$(gh run view "$RUN_ID" -R "$REPO" --json status --jq .status 2>/dev/null || echo unknown)
    if [[ "$status" == unknown ]]; then
      unknown=$((unknown + 1))
      if (( unknown >= 4 )); then die "cannot read the run any more (gh run view failed 4 times): open $RUN_URL"; fi
    else
      unknown=0
      lines=$(gh run view "$RUN_ID" -R "$REPO" --json jobs --jq '.jobs[] | select(.name | test("^(snapshot|sign-blobs|publish-image|publish-npm|github-release|publish-registry)$")) | "    \(.name): \(.status) \(.conclusion)"' 2>/dev/null || true)
      if [[ "$lines" != "$shown" ]]; then
        printf '\n  run %s: %s\n%s\n' "$RUN_ID" "$status" "$lines"
        shown="$lines"
        if [[ "$lines" == *waiting* ]]; then
          warn "A job is waiting: the release environment asks for an approval. Open $RUN_URL, press 'Review deployments', tick release, 'Approve and deploy'."
        fi
      fi
      if [[ "$status" == completed ]]; then return 0; fi
    fi
    sleep 15
  done
}

# wait_green WORKFLOW — show the run of a workflow for the head of main; go on only when it succeeded.
wait_green() {
  local wf="$1" status conclusion url
  while :; do
    read -r status conclusion url < <(gh run list -R "$REPO" -w "$wf" --branch main --commit "$MAIN_SHA" --limit 1 --json status,conclusion,url --jq 'if length == 0 then "none - -" else .[0] | "\(.status) \(.conclusion | if . == null or . == "" then "-" else . end) \(.url)" end' 2>/dev/null || echo "unknown - -")
    if [[ "$status" == completed && "$conclusion" == success ]]; then
      printf '  %s✓ %s%s succeeded: %s\n' "$GREEN" "$wf" "$RESET" "$url"
      return 0
    fi
    if [[ "$status" == none && "$wf" == ci.yml ]]; then
      warn "$wf has no run for the head of main. CI starts none for a change that only touches docs (header of .github/workflows/ci.yml). The latest run of $wf on main:"
      gh run list -R "$REPO" -w "$wf" --branch main --limit 1 --json headSha,status,conclusion,url --jq '.[] | "    \(.headSha[0:7]) \(.status) \(.conclusion) \(.url)"' 2>/dev/null || true
      stop_unless "Is that latest run of $wf on main good enough?"
      return 0
    fi
    warn "$wf for the head of main: $status / $conclusion ${url#-}"
    stop_unless "Check $wf again? (answer no to stop; a stage does not go on while a run is not successful)"
  done
}

banner "Release $TAG on every channel"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Preflight: can $TAG be cut from this machine?"
say "This stage only reads. It changes nothing."
missing=()
for tool in git gh jq cosign node npx curl; do
  have "$tool" || missing+=("$tool")
done
if (( ${#missing[@]} )); then
  for tool in "${missing[@]}"; do warn "$tool is missing"; done
  die "install what is missing (cosign: https://docs.sigstore.dev/cosign/system_config/installation/, node and npx: https://nodejs.org) and re-run."
fi
origin=$(git remote get-url origin 2>/dev/null || true)
case "$origin" in
  *"github.com/$REPO"* | *"github.com:$REPO"*) ;;
  *) die "origin does not point to $REPO: run the wizard from a checkout of that repository." ;;
esac
if git rev-parse -q --verify "refs/tags/$TAG" >/dev/null 2>&1; then
  die "$TAG already exists locally. The wizard never moves or deletes a tag: if it is a leftover, remove it yourself and re-run."
fi
rc=0
git ls-remote --exit-code --tags origin "refs/tags/$TAG" >/dev/null 2>&1 || rc=$?
case "$rc" in
  0) die "$TAG already exists on origin: the release was started. See docs/development/release-pipeline.md (\"If the wizard stops after the tag\")." ;;
  2) ;; # no such tag on origin: what we want
  *) die "could not ask origin about its tags (git ls-remote exited $rc): check the network and your access, then re-run." ;;
esac
if [[ -z "$(git config user.name 2>/dev/null)" || -z "$(git config user.email 2>/dev/null)" ]]; then
  die "git has no user.name or user.email: the annotated tag needs a tagger."
fi
gh auth status >/dev/null 2>&1 || die "gh is not signed in: run 'gh auth login' with an account that administers $REPO, then re-run."
admin=$(gh api "repos/$REPO" --jq .permissions.admin 2>/dev/null || true)
[[ "$admin" == true ]] || die "the gh account is not an administrator of $REPO (the tag ruleset and the release environment need one)."
if ! gh attestation --help >/dev/null 2>&1; then
  warn "this gh has no 'gh attestation' command (the Ubuntu package, 2.45.0, lacks it; 2.101.0 has it)."
  warn "get one that has it: go install github.com/cli/cli/v2/cmd/gh@latest (put the result first on PATH), or see https://cli.github.com"
  die "re-run once 'gh attestation --help' works."
fi
printf '  %s✓ preflight passed%s: %s is free locally and on origin, the tools are here, gh is an administrator of %s\n' "$GREEN" "$RESET" "$TAG" "$REPO"
pause "Press Enter for stage 2"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Exit checks: the campaign reports and the tickets that gate the release"
say "Read what the exit checks of the release found. Nothing is merged or tagged before you confirm."
shopt -s nullglob
reports=(docs/research/raw/*e2e-langfuse-*.md)
shopt -u nullglob
if (( ${#reports[@]} )); then
  say "Campaign reports in this checkout (the newest are the exit checks):"
  for f in "${reports[@]: -4}"; do printf '    %s\n' "$f"; done
else
  note "This checkout holds no campaign report yet: they reach main with the pull request of stage 3 (Files changed → docs/research/raw)."
fi
say "Exit-check tickets of $MILESTONE:"
for n in $EXIT_ISSUES; do
  line=$(gh issue view "$n" -R "$REPO" --json state,title --jq '"\(.state)  \(.title)"' 2>/dev/null || echo "(could not read it)")
  printf '    #%s  %s\n' "$n" "$line"
  open_url "https://github.com/$REPO/issues/$n"
done
stop_unless "Is every finding of the campaign reports triaged, with none blocking the release?"
stop_unless "Is each ticket above merged, or deliberately left for a later release (and still marked Planned in the docs)? (#183, the filter scan, is one of them for v0.2.0)"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Merge the pull request"
say "The release's work reaches main through one pull request. You review and merge it; this wizard never merges."
say "Open pull requests into main:"
gh pr list -R "$REPO" --base main --state open --json number,title,headRefName --jq '.[] | "    #\(.number)  \(.title)  (\(.headRefName))"' 2>/dev/null || true
PR_NUMBER=""
ask PR_NUMBER "Number of the pull request to merge (Enter if it is already merged):"
if [[ -n "$PR_NUMBER" ]]; then
  [[ "$PR_NUMBER" =~ ^[0-9]+$ ]] || die "'$PR_NUMBER' is not a pull request number."
  open_url "https://github.com/$REPO/pull/$PR_NUMBER"
  step "Review it (Files changed), wait for its checks to be green, then press 'Merge pull request'."
  pause "Merged? Press Enter and the wizard checks"
  while :; do
    read -r pr_state pr_sha < <(gh pr view "$PR_NUMBER" -R "$REPO" --json state,mergeCommit --jq '"\(.state) \(.mergeCommit.oid // "-")"' 2>/dev/null || echo "unknown -")
    if [[ "$pr_state" == MERGED ]]; then break; fi
    warn "pull request #$PR_NUMBER is $pr_state, not merged."
    stop_unless "Check again?"
  done
  git fetch --quiet origin main
  if [[ "$pr_sha" != "-" ]]; then
    git merge-base --is-ancestor "$pr_sha" origin/main || die "origin/main does not hold the merge commit $pr_sha of #$PR_NUMBER."
  fi
  printf '  %s✓ origin/main holds the merge of #%s%s\n' "$GREEN" "$PR_NUMBER" "$RESET"
else
  stop_unless "Is everything of this release already on origin/main?"
fi
say "Tickets of $MILESTONE still open (closed by the merge that says Closes #N):"
gh issue list -R "$REPO" --milestone "$MILESTONE" --state open --json number,title --jq '.[] | "    #\(.number)  \(.title)"' 2>/dev/null || true
pause "Press Enter for stage 4"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "main is green"
git fetch --quiet origin main
MAIN_SHA=$(git rev-parse origin/main)
say "Head of main: $(git log -1 --format='%h %s' "$MAIN_SHA")"
say "CI and the Release workflow (snapshot mode: it builds every channel and publishes nothing) must both have succeeded for it."
wait_green ci.yml
wait_green release.yml
pause "Press Enter for stage 5"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Release settings still in place"
say "Four settings decide whether the Release run can publish. Read each, then confirm all four."
note "Pages and menu wording marked (unverified) were not checked against the live service by the author of this wizard."
echo
step "1. Tag ruleset 'release tags': creation, update and deletion of v* tags restricted to administrators."
open_url "https://github.com/$REPO/settings/rules"
gh api "repos/$REPO/rulesets" --jq '.[] | select(.name == "release tags") | "    found: \(.name), target \(.target), enforcement \(.enforcement)"' 2>/dev/null || true
step "2. Environment 'release': deployments limited to tags matching v*."
open_url "https://github.com/$REPO/settings/environments"
gh api "repos/$REPO/environments/release/deployment-branch-policies" --jq '.branch_policies[] | "    found: \(.type) \(.name)"' 2>/dev/null || true
step "3. The GHCR package langfuse-api-mcp is public (the Registry reads its label, users pull it without login)."
open_url "https://github.com/$REPO/pkgs/container/langfuse-api-mcp"
note "(unverified) Package settings → Danger Zone → Change visibility. The check below is anonymous: it passes only if the package is public."
ghcr_token=$(curl -fsS "https://ghcr.io/token?service=ghcr.io&scope=repository:$REPO:pull" 2>/dev/null | jq -r '.token // empty' 2>/dev/null || true)
if [[ -n "$ghcr_token" ]] && curl -fsS -o /dev/null -H "Authorization: Bearer $ghcr_token" "https://ghcr.io/v2/$REPO/tags/list" 2>/dev/null; then
  printf '    %sfound%s: the tag list of ghcr.io/%s is readable without login\n' "$GREEN" "$RESET" "$REPO"
else
  warn "ghcr.io/$REPO could not be read without login: the package may not be public."
fi
unset ghcr_token
step "4. A trusted publisher on each of the seven npm packages (npm docs: https://docs.npmjs.com/trusted-publishers)."
say "   Each must show: GitHub Actions, repository $REPO, workflow release.yml, environment release,"
say "   and direct 'npm publish' allowed (a publisher made after 2026-09-03 allows only 'npm stage publish'"
say "   until you tick it; the Release run runs 'npm publish'). npm checks nothing when a publisher is saved:"
say "   a mistake shows only when the Release run publishes. A publisher whose first successful publish did not"
say "   happen within 2 days of its creation expires (npm docs): delete and recreate it, then tag at once."
note "(unverified) The package settings page is taken to be the address below; npm's docs name it Settings → Publishing access."
gaps=()
for pkg in "${NPM_PACKAGES[@]}"; do
  open_url "https://www.npmjs.com/package/$pkg/access"
  confirm "$pkg: publisher present with workflow release.yml, environment release, 'npm publish' allowed, not expired?" || gaps+=("$pkg")
done
if (( ${#gaps[@]} )); then
  warn "No working publisher on: ${gaps[*]}"
  stop_unless "Go on anyway? (publish-npm would fail to authenticate for them; stage 8 is the token path)"
fi
stop_unless "Are the four settings above in place?"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Tag and push $TAG"
git fetch --quiet origin main
TAG_SHA=$(git rev-parse origin/main)
[[ "$TAG_SHA" == "$MAIN_SHA" ]] || die "origin/main moved since stage 4 (${MAIN_SHA:0:7} is now ${TAG_SHA:0:7}): re-run, so that the checks of stage 4 are those of the commit you tag."
say "Commit: $(git log -1 --format='%H %s' "$TAG_SHA")"
say "Tag:    $TAG, annotated, message '$TAG', on that commit (the way v0.1.0 was made)."
warn "Pushing the tag starts the Release run: it signs and publishes to npm, GHCR, GitHub Releases and the MCP Registry. A publication cannot be undone."
stop_unless "Create the annotated tag $TAG on ${TAG_SHA:0:7} and push it to origin?"
git tag -a "$TAG" -m "$TAG" "$TAG_SHA"
if ! git push origin "refs/tags/$TAG"; then
  die "the push of $TAG was refused (the tag ruleset allows administrators only?). The local tag stays; fix the cause and run: git push origin refs/tags/$TAG"
fi
AFTER_TAG=1
printf '  %s✓ pushed %s%s\n' "$GREEN" "$TAG" "$RESET"
pause "Press Enter to watch the Release run"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Watch the Release run"
for _ in $(seq 1 12); do
  RUN_ID=$(gh run list -R "$REPO" -w release.yml --event push --limit 20 --json databaseId,headBranch --jq ".[] | select(.headBranch == \"$TAG\") | .databaseId" 2>/dev/null | head -n 1 || true)
  if [[ -n "$RUN_ID" ]]; then break; fi
  sleep 5
done
[[ -n "$RUN_ID" ]] || die "no Release run found for $TAG yet: open https://github.com/$REPO/actions/workflows/release.yml"
RUN_URL="https://github.com/$REPO/actions/runs/$RUN_ID"
open_url "$RUN_URL"
say "Waiting for the run to end. If a job waits for an approval of the release environment, this says where to give it."
watch_run
failed=$(gh run view "$RUN_ID" -R "$REPO" --json jobs --jq '[.jobs[] | select(.conclusion == "failure") | .name] | join(" ")' 2>/dev/null || true)
other=""
for j in $failed; do
  case "$j" in publish-npm | publish-registry) ;; *) other="$other $j" ;; esac
done
if [[ -n "$other" ]]; then
  warn "Failed jobs outside the two with a fallback:$other. Read their logs at $RUN_URL; the wizard cannot repair them."
  stop_unless "Go on to the checks anyway?"
fi
say "publish-npm: $(job_conclusion publish-npm)    publish-registry: $(job_conclusion publish-registry)"
pause "Press Enter for stage 8"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "If needed: npm token fallback"
npm_job=$(job_conclusion publish-npm)
if [[ "$npm_job" != failure ]]; then
  say "publish-npm ended as '${npm_job:-unknown}', not as a failure: nothing to do in this stage."
  pause "Press Enter for stage 9"
else
  warn "publish-npm failed. This stage is only for a failure to authenticate."
  say "Open the job log and look for ENEEDAUTH, 'Unable to authenticate' or an E404 on the PUT request."
  open_url "$RUN_URL"
  confirm "Is it an authentication failure?" || die "another cause: read the log of publish-npm; this stage would not help."
  say "The token path of v0.1.0: a short-lived granular token, kept as the secret NPM_TOKEN of the release environment only (the job reads it as NODE_AUTH_TOKEN)."
  open_url "https://www.npmjs.com/"
  step "(unverified menu wording; npm's guide: https://docs.npmjs.com/about-access-tokens)"
  step "Account menu → Access Tokens → Generate New Token → Granular Access Token."
  step "Name release-$TAG, the shortest expiry, permission Read and write, on the seven packages: ${NPM_PACKAGES[*]}"
  step "If the publish asks for a one-time password, the token needs the option that bypasses two-factor authentication for it."
  NPM_TOKEN=""
  ask_secret NPM_TOKEN "Paste the token (hidden; it goes only to the release environment secret):"
  [[ -n "$NPM_TOKEN" ]] || die "no token entered."
  stop_unless "Store the token as the secret NPM_TOKEN of the 'release' environment of $REPO?"
  printf '%s' "$NPM_TOKEN" | gh secret set NPM_TOKEN --env release -R "$REPO"
  unset NPM_TOKEN
  if confirm "Re-run the failed jobs of run $RUN_ID (publish-npm and the jobs after it) now?"; then
    gh run rerun "$RUN_ID" -R "$REPO" --failed
    sleep 10
    watch_run
    say "publish-npm: $(job_conclusion publish-npm)    publish-registry: $(job_conclusion publish-registry)"
  else
    warn "not re-run: the failed jobs stay failed."
  fi
  if confirm "Delete the secret NPM_TOKEN from the release environment now?"; then
    gh secret delete NPM_TOKEN --env release -R "$REPO"
  else
    SKIPPED+=("delete the secret NPM_TOKEN of the release environment: gh secret delete NPM_TOKEN --env release -R $REPO")
  fi
  step "On npmjs.com, revoke the token (Access Tokens → the token → delete)."
  SKIPPED+=("revoke the npm token release-$TAG on npmjs.com if you did not")
  pause "Token revoked? Press Enter"
fi

# ── 9 ────────────────────────────────────────────────────────────────────
stage "If needed: MCP Registry"
reg_job=$(job_conclusion publish-registry)
case "$reg_job" in
  failure)
    warn "publish-registry failed. The Registry is in preview: the release itself is complete without it."
    open_url "$RUN_URL"
    if confirm "Re-run the failed job (publish-registry) of run $RUN_ID now?"; then
      gh run rerun "$RUN_ID" -R "$REPO" --failed
      sleep 10
      watch_run
    else
      SKIPPED+=("re-run publish-registry: gh run rerun $RUN_ID -R $REPO --failed")
    fi
    say "publish-registry: $(job_conclusion publish-registry)"
    open_url "https://registry.modelcontextprotocol.io/v0/servers?search=io.github.rodrigorjsf/langfuse-api-mcp"
    say "Confirm the entry io.github.rodrigorjsf/langfuse-api-mcp lists version $VERSION as latest and active."
    pause "Press Enter for stage 10"
    ;;
  *)
    say "publish-registry ended as '${reg_job:-unknown}', not as a failure: nothing to do in this stage."
    pause "Press Enter for stage 10"
    ;;
esac

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Check the release"
say "Runs the commands of \"Verify what you run\" (docs/reference/security-model.md) for $VERSION, then starts npx."
say "Every output goes to a transcript file. No key is written there, or anywhere."
WORK=$(mktemp -d)
chmod 700 "$WORK"
IDENTITY="https://github.com/$REPO/.github/workflows/release.yml@refs/tags/$TAG"
OIDC_ISSUER="https://token.actions.githubusercontent.com"
{
  printf '# %s release proofs, %s UTC\n' "$TAG" "$(date -u +%FT%TZ)"
  printf 'machine: %s\n' "$(uname -sm)"
  printf 'cosign: %s\n' "$(cosign version 2>&1 | grep -i gitversion || echo unknown)"
  printf 'gh: %s\n' "$(gh --version | head -n 1)"
  printf 'node: %s, npm: %s\n' "$(node -v)" "$(npm -v 2>/dev/null || echo unknown)"
} > "$TRANSCRIPT"
say "Transcript: $TRANSCRIPT"
PASSED=()
FAILED=()

# check "label" command… — run in the download directory; its output goes to the transcript.
check() {
  local label="$1"
  shift
  { printf '\n== %s\n$ %s\n' "$label" "$*"; } >> "$TRANSCRIPT"
  if ( cd "$WORK" && "$@" ) >> "$TRANSCRIPT" 2>&1; then
    PASSED+=("$label")
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$label"
  else
    FAILED+=("$label")
    warn "FAILED: $label (the transcript has the output)"
  fi
}

sha256_check() {
  if have sha256sum; then sha256sum -c checksums.txt; else shasum -a 256 -c checksums.txt; fi
}

verify_blobs() {
  local f
  for f in "langfuse-mcp_${VERSION}_"*.tar.gz "langfuse-mcp_${VERSION}_"*.zip checksums.txt "langfuse-mcp_${VERSION}.mcpb" "langfuse-api-mcp-skill_${VERSION}.zip"; do
    cosign verify-blob --bundle "$f.sigstore.json" --certificate-identity "$IDENTITY" --certificate-oidc-issuer "$OIDC_ISSUER" "$f" || return 1
  done
}

attest_blobs() {
  local f
  for f in "langfuse-mcp_${VERSION}_"*.tar.gz "langfuse-mcp_${VERSION}_"*.zip checksums.txt "langfuse-mcp_${VERSION}.mcpb" "langfuse-api-mcp-skill_${VERSION}.zip"; do
    gh attestation verify "$f" -R "$REPO" || return 1
  done
  gh attestation verify "oci://ghcr.io/$REPO:$VERSION" -R "$REPO"
}

npm_signatures() {
  mkdir -p npm-project && cd npm-project && npm init -y >/dev/null && npm install --ignore-scripts "langfuse-api-mcp@$VERSION" && npm audit signatures
}

registry_entry() {
  curl -fsS "https://registry.modelcontextprotocol.io/v0/servers?search=io.github.rodrigorjsf/langfuse-api-mcp" \
    | jq -e --arg v "$VERSION" '[.servers[]? | (.server // .) | select(.version == $v)] | length > 0'
}

check "release assets downloaded" gh release download "$TAG" -R "$REPO" -D .
check "checksums.txt matches every file it lists" sha256_check
check "cosign verify-blob: archives, checksums.txt, .mcpb, skill ZIP" verify_blobs
check "cosign verify: the image" cosign verify "ghcr.io/$REPO:$VERSION" --certificate-identity "$IDENTITY" --certificate-oidc-issuer "$OIDC_ISSUER"
check "gh attestation verify: the same blobs and the image" attest_blobs
check "npm audit signatures for langfuse-api-mcp@$VERSION" npm_signatures
check "MCP Registry lists $VERSION" registry_entry

say "Now npx: start langfuse-api-mcp@$VERSION against a Langfuse you name and read the version it reports."
LF_URL=""
LF_PK=""
LF_SK=""
ask LF_URL "Langfuse base URL (for example https://cloud.langfuse.com):"
ask LF_PK "Langfuse public key (pk-lf-…):"
ask_secret LF_SK "Langfuse secret key (sk-lf-…, hidden; used by the one process below, written nowhere):"
if [[ -n "$LF_URL" && -n "$LF_PK" && -n "$LF_SK" ]]; then
  init='{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"release-wizard","version":"0"}}}'
  limit=(command)
  if have timeout; then limit=(timeout 120); fi
  # The keys travel as the environment of this one process, never as an argument, never to a file.
  reply=$({ printf '%s\n' "$init"; sleep 20; } | LANGFUSE_BASE_URL="$LF_URL" LANGFUSE_PUBLIC_KEY="$LF_PK" LANGFUSE_SECRET_KEY="$LF_SK" "${limit[@]}" npx -y "langfuse-api-mcp@$VERSION" 2>/dev/null | head -n 1 || true)
  reported=$(printf '%s' "$reply" | jq -r '.result.serverInfo.version // empty' 2>/dev/null || true)
  printf '\n== npx -y langfuse-api-mcp@%s: initialize\nserverInfo.version: %s\n' "$VERSION" "${reported:-none}" >> "$TRANSCRIPT"
  if [[ "$reported" == "$VERSION" ]]; then
    PASSED+=("npx reports $VERSION")
    printf '  %s✓%s npx -y langfuse-api-mcp@%s reports %s\n' "$GREEN" "$RESET" "$VERSION" "$reported"
  else
    FAILED+=("npx reports '${reported:-nothing}', want $VERSION")
    warn "FAILED: npx reported '${reported:-nothing}', not $VERSION (run npx -y langfuse-api-mcp@$VERSION by hand to see why)"
  fi
else
  FAILED+=("npx check skipped: no Langfuse named")
  warn "no Langfuse named: the npx check was skipped."
fi
unset LF_URL LF_PK LF_SK reply
say "Passed ${#PASSED[@]}, failed ${#FAILED[@]}. Transcript: $TRANSCRIPT"
if (( ${#FAILED[@]} )); then
  for f in "${FAILED[@]}"; do warn "$f"; done
  stop_unless "Go on to the closing stage with failed checks? (do not announce the release until they are explained)"
fi
pause "Press Enter for stage 11"

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Close out"
RECORD="docs/research/raw/$(date -u +%F)-$TAG-release-proofs.md"
say "The transcript becomes the record $RECORD, with its row in docs/research/INDEX.md."
say "Give an agent session this request (nothing is claimed about $TAG before that record exists):"
printf '\n    Write %s from the transcript %s,\n' "$RECORD" "$TRANSCRIPT"
printf '    in the form of docs/research/raw/2026-09-30-v0.1.0-release-proofs.md; add its row to\n'
printf '    docs/research/INDEX.md; then update the sentences that say what passed against v0.1.0\n'
printf '    (docs/reference/security-model.md "Verify what you run", ROADMAP.md) to name %s as well.\n\n' "$TAG"
SKIPPED+=("the release-proofs record $RECORD from $TRANSCRIPT (request printed in stage 11)")
milestone_number=$(gh api "repos/$REPO/milestones?state=open&per_page=100" 2>/dev/null | jq -r --arg t "$MILESTONE" '.[] | select(.title == $t) | .number' 2>/dev/null | head -n 1 || true)
say "Spec #$SPEC_ISSUE: $(gh issue view "$SPEC_ISSUE" -R "$REPO" --json state,title --jq '"\(.state)  \(.title)"' 2>/dev/null || echo 'could not read it')"
say "Tickets of $MILESTONE still open:"
gh issue list -R "$REPO" --milestone "$MILESTONE" --state open --json number,title --jq '.[] | "    #\(.number)  \(.title)"' 2>/dev/null || true
if [[ -n "$milestone_number" ]]; then
  stop_unless "Close the milestone '$MILESTONE' now? (the spec and its tickets above should be closed)"
  gh api -X PATCH "repos/$REPO/milestones/$milestone_number" -f state=closed >/dev/null
  printf '  %s✓ closed the milestone%s %s\n' "$GREEN" "$RESET" "$MILESTONE"
else
  warn "no open milestone called '$MILESTONE' (already closed?)."
fi
printf '\n  %s%s released%s  run: %s\n' "$BOLD" "$TAG" "$RESET" "$RUN_URL"
pause "Press Enter for the summary"

finish
